function NfmStyles() {
  return /* @__PURE__ */ import_react24.default.createElement("style", null, `
      :root {
        --nfm-accent:      ${NOTE_ACCENT};
        --nfm-accent-dark: ${NOTE_ACCENT_DARK};
        --nfm-accent-tint: ${NOTE_ACCENT_TINT};
      }

      .nfm {
        display: flex;
        flex-direction: column;
        height: 100%;
        background: var(--paper);
      }

      /* ---------- Header ---------- */
      .nfm-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 10px 16px;
        background: var(--nfm-accent);
        flex-shrink: 0;
        z-index: 5;
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
      }
      .nfm-head.is-draggable { cursor: move; }
      .nfm-head-left {
        display: flex;
        align-items: center;
        gap: 12px;
        min-width: 0;
        flex: 1;
      }
      .nfm-head-right {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        flex-shrink: 0;
      }
      .nfm-grip {
        color: rgba(255, 255, 255, 0.7);
        font-size: 14px;
        flex-shrink: 0;
      }
      .nfm-title {
        margin: 0;
        font-family: var(--font-display);
        font-size: 17px;
        font-weight: 600;
        color: var(--paper);
        display: inline-flex;
        align-items: center;
        gap: 8px;
        min-width: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .nfm-title i { font-size: 14px; opacity: 0.85; }
      .nfm-head-pill {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 4px 10px;
        background: rgba(255, 255, 255, 0.15);
        border: 1px solid rgba(255, 255, 255, 0.3);
        border-radius: var(--r-sm);
        color: var(--paper);
        font-family: var(--font-body);
        font-size: 12px;
        font-weight: 500;
        cursor: pointer;
        transition: background 0.15s, border-color 0.15s;
        flex-shrink: 0;
      }
      .nfm-head-pill:hover {
        background: rgba(255, 255, 255, 0.25);
        border-color: rgba(255, 255, 255, 0.5);
      }
      .nfm-head-icon {
        width: 30px;
        height: 30px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        background: rgba(255, 255, 255, 0.15);
        border: none;
        border-radius: 50%;
        color: var(--paper);
        cursor: pointer;
        font-size: 13px;
        transition: background 0.15s, color 0.15s;
      }
      .nfm-head-icon:hover { background: rgba(255, 255, 255, 0.3); }
      .nfm-head-icon-danger:hover { background: rgba(255, 255, 255, 0.2); color: #ffd0d0; }

      /* Save status pill */
      .nfm-save {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 4px 10px;
        background: var(--paper);
        border-radius: var(--r-sm);
        font-family: var(--font-body);
        font-size: 11.5px;
        font-weight: 500;
      }
      .nfm-save.is-pending { color: var(--ink-3); }
      .nfm-save.is-saving  { color: var(--nfm-accent-dark); }
      .nfm-save.is-saved   { color: var(--success); }
      .nfm-save.is-error   { color: var(--error); }
      .nfm-save.is-idle    { color: var(--ink-3); }

      /* ---------- Error banner ---------- */
      .nfm-error {
        margin: 12px 24px 0;
        padding: 10px 14px;
        background: color-mix(in srgb, var(--error) 8%, transparent);
        border: 1px solid color-mix(in srgb, var(--error) 30%, transparent);
        border-radius: var(--r-md);
        color: var(--error);
        font-family: var(--font-body);
        font-size: 13px;
      }
      .nfm-error i { margin-right: 6px; }

      /* ---------- Body (sidebar nav + content) ---------- */
      .nfm-body {
        flex: 1;
        display: flex;
        min-height: 0;
        overflow: hidden;
      }
      .nfm-nav {
        width: 200px;
        flex-shrink: 0;
        background: var(--paper-soft);
        border-right: 1px solid var(--ink-line);
        padding: 16px 12px;
        display: flex;
        flex-direction: column;
        gap: 4px;
      }
      .nfm-nav-label {
        font-family: var(--font-body);
        font-size: 10.5px;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--ink-3);
        margin-bottom: 6px;
        padding: 0 6px;
      }
      .nfm-tab {
        display: flex;
        align-items: center;
        gap: 10px;
        padding: 8px 10px;
        background: transparent;
        border: none;
        border-radius: var(--r-sm);
        cursor: pointer;
        font-family: var(--font-body);
        font-size: 13px;
        color: var(--ink-2);
        text-align: left;
        transition: background 0.12s, color 0.12s;
      }
      .nfm-tab:hover { background: var(--hover); }
      .nfm-tab.is-active {
        background: var(--nfm-accent-tint);
        color: var(--nfm-accent-dark);
        font-weight: 500;
      }
      .nfm-tab i { width: 14px; font-size: 12px; }

      .nfm-content {
        flex: 1;
        overflow-y: auto;
        background: var(--paper);
        padding: 24px 32px 80px;
        min-width: 0;
      }
      .nfm-section { display: flex; flex-direction: column; gap: 18px; }

      /* ---------- Field component ---------- */
      .nfm-field { display: flex; flex-direction: column; gap: 6px; }
      .nfm-field-head {
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 8px;
      }
      .nfm-label {
        font-family: var(--font-body);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--nfm-accent-dark);
      }
      .nfm-req { color: var(--error); margin-left: 4px; }
      .nfm-grid-2 {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 18px;
      }

      .nfm-pin {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding-top: 22px;
        font-family: var(--font-body);
        font-size: 13px;
        color: var(--ink-2);
        cursor: pointer;
      }
      .nfm-pin input { accent-color: var(--nfm-accent); }

      /* ---------- Quoted passage ---------- */
      .nfm-quote {
        margin: 0;
        padding: 10px 14px;
        background: var(--paper-soft);
        border-left: 3px solid var(--nfm-accent);
        border-radius: var(--r-sm);
        font-family: var(--font-body);
        font-size: 13.5px;
        line-height: 1.55;
        color: var(--ink-2);
        font-style: italic;
        white-space: pre-wrap;
      }
      .nfm-quote-detach {
        background: transparent;
        border: none;
        color: var(--ink-3);
        cursor: pointer;
        font-family: var(--font-body);
        font-size: 11.5px;
        padding: 0;
      }
      .nfm-quote-detach:hover { color: var(--error); }
      .nfm-quote-detach i { margin-right: 4px; }

      /* ---------- Editor + toolbar ---------- */
      .nfm-editor {
        border: 1px solid var(--ink-line);
        border-radius: var(--r-md);
        background: var(--paper);
        overflow: hidden;
      }
      .nfm-tb {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 4px;
        padding: 8px;
        border-bottom: 1px solid var(--ink-line-soft);
        background: var(--paper);
      }
      .nfm-tb-btn {
        width: 30px;
        height: 28px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 0;
        background: transparent;
        border: none;
        border-radius: var(--r-sm);
        color: var(--nfm-accent-dark);
        cursor: pointer;
        font-size: 12.5px;
        transition: background 0.12s, color 0.12s;
      }
      .nfm-tb-btn:hover:not(:disabled) {
        background: color-mix(in srgb, var(--nfm-accent) 12%, transparent);
      }
      .nfm-tb-btn.is-active {
        background: color-mix(in srgb, var(--nfm-accent) 22%, transparent);
        color: var(--nfm-accent-dark);
      }
      .nfm-tb-btn:disabled {
        opacity: 0.4;
        cursor: not-allowed;
      }
      .nfm-tb-btn-trail { margin-left: auto; }
      .nfm-tb-divider {
        width: 1px;
        height: 22px;
        background: color-mix(in srgb, var(--nfm-accent) 25%, transparent);
        margin: 0 4px;
      }
      .nfm-tb-select {
        padding: 4px 8px;
        background: var(--paper);
        border: 1px solid color-mix(in srgb, var(--nfm-accent) 25%, var(--ink-line));
        border-radius: var(--r-sm);
        font-family: var(--font-body);
        font-size: 12.5px;
        color: var(--nfm-accent-dark);
        cursor: pointer;
      }
      .nfm-tb-color {
        width: 30px;
        height: 26px;
        padding: 0;
        background: transparent;
        border: 1px solid color-mix(in srgb, var(--nfm-accent) 25%, var(--ink-line));
        border-radius: var(--r-sm);
        cursor: pointer;
      }

      .nfm-prose {
        padding: 12px 16px;
        min-height: 180px;
        font-family: var(--font-body);
        font-size: 14.5px;
        line-height: 1.7;
        color: var(--ink);
      }
      .nfm-prose .ProseMirror { outline: none; min-height: 160px; }
      .nfm-prose .ProseMirror p { margin: 0 0 12px; }
      .nfm-prose .ProseMirror p:last-child { margin: 0; }
      .nfm-prose .ProseMirror ul,
      .nfm-prose .ProseMirror ol { margin: 0 0 12px; padding-left: 22px; }
      .nfm-prose .ProseMirror ul ul,
      .nfm-prose .ProseMirror ol ol,
      .nfm-prose .ProseMirror ul ol,
      .nfm-prose .ProseMirror ol ul { margin-bottom: 0; }
      .nfm-prose .ProseMirror li { margin-bottom: 4px; }
      .nfm-prose .ProseMirror blockquote {
        border-left: 3px solid var(--ink-line);
        padding-left: 14px;
        color: var(--ink-2);
        font-style: italic;
        margin: 0 0 12px;
      }
      .nfm-prose .ProseMirror pre {
        background: var(--paper-soft);
        padding: 10px 12px;
        border-radius: var(--r-sm);
        overflow-x: auto;
      }
      .nfm-prose .ProseMirror code {
        background: var(--paper-soft);
        padding: 1px 5px;
        border-radius: 2px;
        font-family: var(--font-mono);
        font-size: 12.5px;
      }
      .nfm-prose .ProseMirror table {
        border-collapse: collapse;
        width: 100%;
        margin: 0 0 12px;
      }
      .nfm-prose .ProseMirror table td,
      .nfm-prose .ProseMirror table th {
        border: 1px solid var(--ink-line);
        padding: 6px 8px;
      }
      .nfm-prose .ProseMirror table th {
        background: var(--paper-soft);
        text-align: left;
      }
      .nfm-prose .ProseMirror img { max-width: 100%; height: auto; }

      /* ---------- Footer (new-note submit row) ---------- */
      .nfm-foot {
        display: flex;
        justify-content: flex-end;
        align-items: center;
        gap: 10px;
        padding: 14px 24px;
        border-top: 1px solid var(--ink-line);
        background: var(--paper-soft);
        flex-shrink: 0;
      }
      .nfm-foot-create {
        background: var(--nfm-accent);
        border-color: var(--nfm-accent);
        color: var(--paper);
      }
      .nfm-foot-create:hover {
        background: var(--nfm-accent-dark);
        border-color: var(--nfm-accent-dark);
      }

      /* ---------- Floating window mode ---------- */
      .nfm-floating {
        position: fixed;
        width: min(540px, calc(100vw - 16px));
        height: min(680px, calc(100vh - 16px));
        background: var(--paper);
        border-radius: var(--r-lg);
        box-shadow: 0 16px 48px rgba(0, 0, 0, 0.28);
        z-index: 9999;
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }

      /* ---------- Fullscreen mode ---------- */
      .nfm-fullscreen {
        position: fixed;
        inset: 0;
        z-index: 10000;
        background: var(--paper);
        display: flex;
        flex-direction: column;
      }
      .nfm-fs-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 8px 14px;
        background: var(--paper-soft);
        border-bottom: 1px solid var(--ink-line);
        flex-shrink: 0;
      }
      .nfm-fs-head-left {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        min-width: 0;
      }
      .nfm-fs-exit {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 6px 10px;
        background: var(--nfm-accent);
        color: var(--paper);
        border: none;
        border-radius: var(--r-sm);
        font-family: var(--font-body);
        font-size: 12.5px;
        font-weight: 500;
        cursor: pointer;
      }
      .nfm-fs-exit:hover { background: var(--nfm-accent-dark); }
      .nfm-fs-title {
        font-family: var(--font-body);
        font-size: 13px;
        color: var(--ink-2);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
      .nfm-fs-body {
        flex: 1;
        overflow-y: auto;
        padding: 24px;
        max-width: 920px;
        width: 100%;
        margin: 0 auto;
      }
      .nfm-prose-fs { padding: 0; min-height: calc(100vh - 200px); font-size: 16px; }

      /* ---------- Responsive ---------- */
      @media (max-width: 768px) {
        .nfm-nav {
          width: 56px;
          padding: 12px 8px;
        }
        .nfm-nav-label { display: none; }
        .nfm-tab {
          justify-content: center;
          padding: 8px;
        }
        .nfm-tab span { display: none; }
        .nfm-content { padding: 16px 16px 60px; }
        .nfm-grid-2 { grid-template-columns: 1fr; }
        .nfm-pin { padding-top: 0; }
        .nfm-head-pill span { display: none; }
      }
    `);
}

